import React, { useState, useRef, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./Ubicaciones.css";

export default function Ubicaciones() {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([
    { type: "bot", content: "¿Qué edificio o salón te gustaría saber su ubicación?" },
  ]);
  const [inputValue, setInputValue] = useState("");
  const [showMap, setShowMap] = useState(false);
  const chatEndRef = useRef(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSendMessage = () => {
    if (!inputValue.trim()) return;
    const userMessage = { type: "user", content: inputValue };
    const botResponse = generateBotResponse(inputValue);
    setMessages((prev) => [...prev, userMessage, ...botResponse]);
    setInputValue("");
  };

  const generateBotResponse = (userInput) => {
    const input = userInput.toLowerCase();
    if (input.includes("edificio a")) {
      return [
        {
          type: "bot",
          content:
            "Sigue estas indicaciones para llegar al Edificio A, además te dejo una foto del edificio.",
        },
        { type: "bot", content: "map_only", mapImage: "/mapa_tec.png" },
        { type: "bot", content: "building_image", buildingImage: "/Escuela_tec.jpg" },
        {
          type: "bot",
          content:
            "Si quieres saber otra ubicación, escríbela en el chat. Para salir al menú principal, presiona 'Salir'.",
          actions: [{ label: "Salir", action: "exit" }],
        },
      ];
    }

    return [
      {
        type: "bot",
        content:
          "Lo siento, no tengo información sobre esa ubicación. Intenta con otro edificio o salón.",
      },
    ];
  };

  const handleActionClick = (action) => {
    if (action === "exit") navigate("/");
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSendMessage();
  };

  return (
    <div className="ubicaciones-container">
      <header className="ubicaciones-header">
        <button className="name-button" onClick={() => navigate("/")}>
          TalkinPon
        </button>

        <div className="title-logo">
          <h1>Ubicaciones</h1>
          <button
            className="map-toggle-button"
            onClick={() => setShowMap(!showMap)}
          >
            {showMap ? "Ocultar Mapa" : "Mostrar Mapa"}
          </button>
          <div className="heade-logo">
            <img src="/logo-app.png" alt="Logo" />
          </div>
        </div>
      </header>

      <div className="chat-area">
        {messages.map((message, idx) => (
          <div key={idx} className={`chat-message ${message.type}`}>
            <div className="avatar">
              <img
                src={message.type === "bot" ? "/logo-app.png" : "/img-user.png"}
                alt={message.type === "bot" ? "Bot" : "User"}
              />
            </div>

            <div className="message-with-actions">
              {message.content === "map_only" ? (
                <div className="message-box bot">
                  <img
                    src={message.mapImage}
                    alt="Mapa del campus"
                    className="map-image"
                  />
                </div>
              ) : message.content === "building_image" ? (
                <div className="message-box bot">
                  <img
                    src={message.buildingImage}
                    alt="Edificio"
                    className="building-image"
                  />
                </div>
              ) : (
                <div className={`message-box ${message.type}`}>
                  <p>{message.content}</p>
                </div>
              )}

              {message.actions && (
                <div className="actions-row">
                  {message.actions.map((action, i) => (
                    <button
                      key={i}
                      className="action-button"
                      onClick={() => handleActionClick(action.action)}
                    >
                      {action.label}
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>
        ))}
        <div ref={chatEndRef}></div>
      </div>

      {showMap && (
        <div className="map-area">
          <h3>Mapa del Campus</h3>
          <img src="/mapa_tec.png" alt="Mapa campus" className="mapa-campus" />
          <p className="map-caption">Mapa interactivo del campus universitario</p>
        </div>
      )}

      <div className="input-area p-3 border-top">
        <div className="input-group">
          <input
            type="text"
            className="form-control"
            placeholder="Escribe tu mensaje..."
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyPress={handleKeyPress}
          />
          <button className="btn btn-dark" onClick={handleSendMessage}>
            <i className="bi bi-send-fill"></i>
          </button>
        </div>
      </div>
    </div>
  );
}
